'use client'

import { IconSparkles } from '@tabler/icons-react'
import { useRef } from 'react'
import { Button } from '@/components/ui/button'
import { anchoredToastManager } from '@/components/ui/toast'
import { Tooltip, TooltipPopup, TooltipTrigger } from '@/components/ui/tooltip'

const ANCHORED_SAVE_ERROR_TOAST_ID = 'space-demo-anchored-save-error-toast'

export default function Demo() {
  const saveButtonRef = useRef<HTMLButtonElement>(null)
  const toastTimeout = 2000

  function handleSave() {
    if (!saveButtonRef.current) return
    anchoredToastManager.add({
      data: {
        tooltipStyle: true,
      },
      id: ANCHORED_SAVE_ERROR_TOAST_ID,
      positionerProps: {
        anchor: saveButtonRef.current,
        sideOffset: 6,
      },
      timeout: toastTimeout,
      title: "Couldn't save draft",
      type: 'error',
    })
  }

  return (
    <Tooltip>
      <TooltipTrigger
        delay={0}
        render={<Button aria-label="Save" onClick={handleSave} ref={saveButtonRef} size="icon" variant="outline" />}
      >
        <IconSparkles aria-hidden="true" />
      </TooltipTrigger>
      <TooltipPopup>
        <p>Save</p>
      </TooltipPopup>
    </Tooltip>
  )
}
